async def act(page):
    """
    1) Dismiss any obvious popup that might block interactions.
    2) Use the visible search widget inside role="main" to search for 'diabetes' (via full role path).
    3) Wait for results and click the bottom result (final action). Use robust fallbacks.
    """
    import asyncio

    # 1) Try to close a visible popup using accessible button names/aria-labels
    try:
        close_names = ["×", "✕", "Close", "close", "Dismiss"]
        closed = False
        for name in close_names:
            try:
                btns = page.get_by_role("button", name=name)
                if await btns.count() > 0:
                    await btns.nth(0).click()
                    await asyncio.sleep(0.25)
                    closed = True
                    break
            except Exception:
                pass

        if not closed:
            # Fallback: scan buttons for aria-label or inner_text containing 'close' or close glyphs
            all_buttons = page.get_by_role("button")
            try:
                total = await all_buttons.count()
            except Exception:
                total = 0
            for i in range(total):
                try:
                    aria = (await all_buttons.nth(i).get_attribute("aria-label")) or ""
                    text = ""
                    try:
                        text = (await all_buttons.nth(i).inner_text()).strip()
                    except Exception:
                        text = ""
                    combined = " ".join([aria, text]).strip()
                    if combined and ("close" in combined.lower() or "×" in combined or "✕" in combined):
                        await all_buttons.nth(i).click()
                        await asyncio.sleep(0.25)
                        break
                except Exception:
                    continue
    except Exception:
        # non-fatal; continue
        pass

    # 2) Use the site's visible search widget inside main -> search -> searchbox & button.
    main = page.get_by_role("main")
    try:
        await main.wait_for(state="visible", timeout=3000)
    except Exception:
        # small pause to stabilize
        await asyncio.sleep(0.25)

    try:
        search_region = main.get_by_role("search")
        # prefer explicit searchbox named "Search"
        try:
            searchbox = search_region.get_by_role("searchbox", name="Search")
        except Exception:
            # fallback to any searchbox inside the region
            searchbox = search_region.get_by_role("searchbox")
        # ensure we have a locator and at least one element
        if await searchbox.count() > 0:
            await searchbox.nth(0).fill("diabetes")
            # Click the Search button inside the same search region (full path)
            try:
                search_button = search_region.get_by_role("button", name="Search")
            except Exception:
                search_button = search_region.get_by_role("button")
            if await search_button.count() > 0:
                await search_button.nth(0).click()
            else:
                # fallback: press Enter in the searchbox
                await searchbox.nth(0).press("Enter")
        else:
            # Fallback: try any searchbox on the page
            generic_searchbox = page.get_by_role("searchbox")
            if await generic_searchbox.count() > 0:
                await generic_searchbox.nth(0).fill("diabetes")
                await generic_searchbox.nth(0).press("Enter")
    except Exception:
        # If search interaction fails, continue — results may already be present.
        pass

    # 3) Wait for results to render and click the bottom result.
    try:
        await main.wait_for(state="visible", timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            await asyncio.sleep(0.5)

    # Attempt to click the bottom result via headings (per accessibility tree)
    try:
        headings = main.get_by_role("heading")
        hcount = 0
        try:
            hcount = await headings.count()
        except Exception:
            hcount = 0

        if hcount > 0:
            last_heading = headings.nth(hcount - 1)
            # Try clicking a link inside the heading (preferred final action)
            try:
                links_in_heading = last_heading.get_by_role("link")
                if await links_in_heading.count() > 0:
                    await links_in_heading.nth(0).click()
                    return
            except Exception:
                pass
            # If no link inside heading, click the heading itself
            try:
                await last_heading.click()
                return
            except Exception:
                pass
    except Exception:
        # Continue to other fallbacks
        pass

    # Fallback: click the last article's first link if article elements exist
    try:
        articles = main.get_by_role("article")
        acount = 0
        try:
            acount = await articles.count()
        except Exception:
            acount = 0
        if acount > 0:
            last_article = articles.nth(acount - 1)
            try:
                links = last_article.get_by_role("link")
                if await links.count() > 0:
                    await links.nth(0).click()
                    return
            except Exception:
                pass
            try:
                await last_article.click()
                return
            except Exception:
                pass
    except Exception:
        pass

    # Final fallback: click the last link in main if any
    try:
        links_in_main = main.get_by_role("link")
        lcount = 0
        try:
            lcount = await links_in_main.count()
        except Exception:
            lcount = 0
        if lcount > 0:
            await links_in_main.nth(lcount - 1).click()
            return
    except Exception:
        pass

    # Nothing clickable found; finish.
    return

